/**
 * PathfindingHelper - 3D debug visualization for agent paths.
 *
 * @extends THREE.Object3D
 */
export class PathfindingHelper {
    /**
     * Create a pathfinding helper.
     *
     * @param {PathfindingGrid} grid - The pathfinding grid reference.
     * @param {Object} [options={}] - Configuration options.
     * @param {number} [options.updateInterval=100] - Update interval in ms.
     * @param {number} [options.pathColor=0x00ff88] - Path line color.
     * @param {number} [options.activeColor=0x00ffff] - Active segment color.
     * @param {number} [options.bodyLineColor=0xff0000] - Body to path line color.
     * @param {number} [options.waypointColor=0xffffff] - Waypoint marker color.
     * @param {number} [options.destinationColor=0xff6688] - Destination marker color.
     * @param {boolean} [options.showWaypoints=true] - Show waypoint markers.
     * @param {boolean} [options.showDestination=true] - Show destination marker.
     * @param {boolean} [options.showBodyLine=true] - Show line from body to first waypoint.
     * @param {number} [options.yOffset=0.1] - Y offset for path lines.
     */
    constructor(grid: PathfindingGrid, options?: {
        updateInterval?: number;
        pathColor?: number;
        activeColor?: number;
        bodyLineColor?: number;
        waypointColor?: number;
        destinationColor?: number;
        showWaypoints?: boolean;
        showDestination?: boolean;
        showBodyLine?: boolean;
        yOffset?: number;
    });
    /**
     * Reference to the pathfinding grid.
     * @type {PathfindingGrid}
     */
    grid: PathfindingGrid;
    /**
     * Update interval in milliseconds.
     * @type {number}
     */
    updateInterval: number;
    /**
     * Y offset for visualization elements.
     * @type {number}
     */
    yOffset: number;
    _showWaypoints: boolean;
    _showDestination: boolean;
    _showBodyLine: boolean;
    _pathColor: number;
    _activeColor: number;
    _bodyLineColor: number;
    _waypointColor: number;
    _destinationColor: number;
    _lastUpdate: number;
    _pathLines: Map<any, any>;
    _activeLines: Map<any, any>;
    _bodyLines: Map<any, any>;
    _waypointMeshes: Map<any, any>;
    _destinationMeshes: Map<any, any>;
    _fetchPending: boolean;
    _pathMaterial: any;
    _activeMaterial: any;
    _bodyLineMaterial: any;
    _waypointMaterial: any;
    _destinationMaterial: any;
    _waypointGeometry: any;
    _destinationGeometry: any;
    _matrix: any;
    _position: any;
    _scale: any;
    _quaternion: any;
    set showWaypoints(value: boolean);
    /**
     * Whether to show waypoint markers.
     * @type {boolean}
     */
    get showWaypoints(): boolean;
    set showDestination(value: boolean);
    /**
     * Whether to show destination markers.
     * @type {boolean}
     */
    get showDestination(): boolean;
    set showBodyLine(value: boolean);
    /**
     * Whether to show body to first waypoint line.
     * @type {boolean}
     */
    get showBodyLine(): boolean;
    /**
     * Update debug visualization - call each frame.
     */
    update(): void;
    /**
     * Fetch path data and render.
     *
     * @private
     */
    private _fetchAndRender;
    /**
     * Render all agent paths.
     *
     * @param {Object} pathData - Map of agent key to path data.
     * @private
     */
    private _renderPaths;
    /**
     * Render path for a single agent.
     *
     * @param {string} agentKey - Agent key.
     * @param {Object} data - Path data.
     * @private
     */
    private _renderAgentPath;
    /**
     * Create a line with pre-allocated buffer.
     *
     * @param {THREE.Material} material - Line material.
     * @param {number} maxVertices - Maximum vertices.
     * @returns {Object} { line, positionAttr }
     * @private
     */
    private _createLine;
    /**
     * Update or create path line for agent.
     *
     * @param {string} agentKey - Agent key.
     * @param {Array} path - Path waypoints.
     * @private
     */
    private _updatePathLine;
    /**
     * Update or create active segment line.
     *
     * @param {string} agentKey - Agent key.
     * @param {Array} path - Path waypoints.
     * @param {number} pathIndex - Current waypoint index.
     * @private
     */
    private _updateActiveLine;
    /**
     * Update or create body to first waypoint line.
     *
     * @param {string} agentKey - Agent key.
     * @param {Array} bodyPos - Body position.
     * @param {Array} firstWaypoint - First waypoint.
     * @private
     */
    private _updateBodyLine;
    /**
     * Update waypoint markers.
     *
     * @param {string} agentKey - Agent key.
     * @param {Array} path - Path waypoints.
     * @param {number} pathIndex - Current waypoint index.
     * @private
     */
    private _updateWaypoints;
    /**
     * Update destination marker.
     *
     * @param {string} agentKey - Agent key.
     * @param {Array} destination - Destination position.
     * @private
     */
    private _updateDestination;
    /**
     * Remove visuals for an agent.
     *
     * @param {string} agentKey - Agent key.
     * @private
     */
    private _removeAgentVisuals;
    /**
     * Clean up visuals for inactive agents.
     *
     * @param {Set} activeAgents - Set of active agent keys.
     * @private
     */
    private _cleanupInactiveAgents;
    /**
     * Dispose of the helper and release resources.
     */
    dispose(): void;
}
